mapper.select:
SELECT p.id, p.title, a.name AS artist_name, l.name AS label_name, p.price, p.color_variant, p.pressing_info, p.status, (SELECT MIN(i.image_url) FROM product_image i WHERE i.product_id = p.id AND i.sort_order = 0) AS thumbnail_url, p.avg_rating AS average_rating, p.review_count AS review_count,
EXISTS (SELECT 1 FROM wishlist w WHERE w.product_id = p.id AND w.member_id = #{memberId})
NULL AS wishlisted FROM product p JOIN artist a ON a.id = p.artist_id LEFT JOIN label l ON l.id = p.label_id WHERE p.status <> 'HIDDEN' AND p.id IN #{id}

SELECT product_id
FROM product_view_log
WHERE member_id = #{memberId}
GROUP BY product_id
ORDER BY MAX(viewed_at) DESC
LIMIT #{limit}
